import { Card, Container } from "react-bootstrap";
import Name from "./Name";
import Price from "./Price";
import Description from "./Description";
import Image from "./Image";

// Variable à renseigner : si vide, un message générique s'affiche
const firstName = "Theo";

function App() {
  return (
    <Container className="d-flex flex-column align-items-center py-5">
      <Card style={{ width: "22rem" }} className="shadow-sm">
        <Image />
        <Card.Body>
          <Name />
          <Price />
          <Description />
        </Card.Body>
      </Card>

      <div className="mt-4 text-center">
        <h4>{firstName ? `Hello, ${firstName}` : "Hello, there !"}</h4>
        {firstName && (
          <img
            src="https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=300&q=80"
            alt="Salutation"
            style={{ width: "180px", borderRadius: "8px", marginTop: "0.5rem" }}
          />
        )}
      </div>
    </Container>
  );
}

export default App;
